{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Integrative, person-centered sessions that draw from nutrition, movement, breathwork and lifestyle medicine to support resilience and clarity.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <svg width="0" height="0" style="position:absolute;left:-9999px;">
    <defs>
      <pattern id="sitePattern" patternUnits="userSpaceOnUse" width="40" height="40">
        <rect width="40" height="40" fill="#f7f5f2"></rect>
        <path d="M0 20 L20 0 M20 40 L40 20" stroke="#e6e2db" stroke-width="1.5"/>
        <circle cx="10" cy="30" r="1.2" fill="#d7cbbf" />
      </pattern>
    </defs>
  </svg>

  <header class="site-header">
    <div class="brand">
      <div class="logo-mark" aria-hidden="true"></div>
      <div>
        <h1>{{BUSINESS_NAME}}</h1>
        <p class="tag">{{TAGLINE}}</p>
      </div>
    </div>
    <nav class="main-nav">
      <a href="/">Home</a>
      <a href="/services.html">Offerings</a>
      <a href="/approach.html">Approach</a>
      <a href="/pricing.html">Programs</a>
      <a href="/about.html">About</a>
      <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal" id="hero">
      <div class="hero-inner">
        <h2>Care that tunes to your whole day — not just the moment you arrive</h2>
        <p>Practical, integrative consultations combining lifestyle guidance, gentle movement, breath practice and evidence-informed herbal or nutrient suggestions where appropriate.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Meet the practitioner</a>
        </div>
      </div>
      <svg class="hero-pattern" viewBox="0 0 200 200" aria-hidden="true">
        <rect width="200" height="200" fill="url(#sitePattern)"></rect>
      </svg>
    </section>

    <!-- Story (reordered) -->
    <section class="story reveal" id="story">
      <div class="container">
        <h3>Gentle detective work — what matters most to you</h3>
        <p>We listen for patterns in sleep, stress, digestion and movement. From there we co-design steps you can try between visits: small, trackable, and situated in your life.</p>
        <ul class="features">
          <li><strong>Personal rhythm mapping</strong><span>We map what your days look like and find leverage points for steady improvement.</span></li>
          <li><strong>Tangible micro-practices</strong><span>Short, practical actions you can integrate without overhauling life.</span></li>
          <li><strong>Evidence-aware recommendations</strong><span>Choices are framed with what science suggests and what suits you.</span></li>
        </ul>
      </div>
    </section>

    <!-- Framework -->
    <section class="framework reveal" id="framework">
      <div class="container">
        <h3>How a session flows</h3>
        <ol class="flow">
          <li><strong>Open conversation</strong><span>We explore what brought you in and what matters now.</span></li>
          <li><strong>Pattern discovery</strong><span>We surface habits and triggers and spot small shifts with big effect.</span></li>
          <li><strong>Plan & practice</strong><span>A short, personalized plan to try before the next visit.</span></li>
          <li><strong>Follow-up options</strong><span>Email summaries, brief check-ins, or program pathways.</span></li>
        </ol>
      </div>
    </section>

    <!-- Offers with Session Planner widget -->
    <section class="offers reveal" id="offers">
      <div class="container">
        <h3>Services and ways to work together</h3>
        <div class="cards">
          <article class="card">
            <h4>Starter Session</h4>
            <p class="price">$95 — 50 min</p>
            <p>An in-depth first visit to map concerns, set priorities and craft a short trial plan.</p>
          </article>
          <article class="card">
            <h4>Guided Mini-Series</h4>
            <p class="price">$270 — 3 sessions</p>
            <p>Three focused sessions supporting a single goal with checkpoints and small, measurable practices.</p>
          </article>
          <article class="card">
            <h4>Monthly Support</h4>
            <p class="price">$420/month</p>
            <p>Ongoing monthly time with notes and brief mid-cycle check-ins for steady progress.</p>
          </article>
        </div>

        <div class="planner" aria-labelledby="plannerTitle">
          <h4 id="plannerTitle">Session Planner — design your first 4-week plan</h4>
          <form id="plannerForm">
            <label>Primary goal
              <select id="goal">
                <option value="Better sleep">Better sleep</option>
                <option value="Reduce overwhelm">Reduce overwhelm</option>
                <option value="Digestive ease">Digestive ease</option>
                <option value="More energy">More energy</option>
              </select>
            </label>
            <label>Preferred modalities
              <select id="modalities" multiple>
                <option value="Breathwork">Breathwork</option>
                <option value="Movement">Movement</option>
                <option value="Nutrition support">Nutrition support</option>
                <option value="Herbal or nutrient suggestions">Herbal or nutrient suggestions</option>
              </select>
            </label>
            <label>Time you can commit per day
              <input id="dailyMinutes" type="number" min="0" max="60" value="10"> minutes
            </label>
            <label>Availability per week
              <select id="frequency">
                <option value="1">1 session/week</option>
                <option value="2">2 sessions/week</option>
                <option value="0.5">Fortnightly</option>
              </select>
            </label>
            <label>Notes / Constraints
              <textarea id="notes" placeholder="Allergies, equipment, schedule notes..."></textarea>
            </label>
            <div class="planner-actions">
              <button type="button" class="btn" id="buildPlan">Build plan</button>
              <button type="button" class="btn ghost" id="clearPlan">Reset</button>
            </div>
          </form>

          <div class="plan-output" aria-live="polite">
            <h5>Your 4-week plan</h5>
            <pre id="planText">No plan yet. Use the builder to generate a simple outline you can try.</pre>
            <div class="output-actions">
              <button class="btn primary" id="copyPlan">Copy summary</button>
              <a class="btn" id="downloadPlan" href="#" download="session-plan.txt">Download .txt</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Pricing -->
    <section class="pricing reveal" id="pricing">
      <div class="container">
        <h3>Programs and pricing</h3>
        <p>Options are framed to meet the moment you are in — single sessions, short series for concentrated work, and monthly care for ongoing goals.</p>
        <div class="pricing-grid">
          <div class="tier">
            <h4>Single Session</h4>
            <p class="cost">$95</p>
            <p>One 50-minute session with a written summary and suggested steps.</p>
          </div>
          <div class="tier featured">
            <h4>Focused Series</h4>
            <p class="cost">$270</p>
            <p>Series of three sessions to tackle a specific concern with measurable checkpoints.</p>
          </div>
          <div class="tier">
            <h4>Monthly Care</h4>
            <p class="cost">$420/mo</p>
            <p>Ongoing support including brief check-ins and plan adjustments.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Testimonials -->
    <section class="testimonials reveal" id="testimonials">
      <div class="container">
        <h3>People often say</h3>
        <blockquote>
          "This felt like practical coaching — small steps that actually fit into my day. Follow-ups helped keep things realistic."
          <cite>— a local client</cite>
        </blockquote>
        <blockquote>
          "I appreciated the clear notes and a plan I could test over the month; it felt collaborative and sensible."
          <cite>— another client</cite>
        </blockquote>
      </div>
    </section>

    <!-- Call to Action -->
    <section class="cta reveal" id="cta">
      <div class="container">
        <h3>Ready to shape your next steps?</h3>
        <p>Book a starter session to map a plan you can try. Email summaries and optional short check-ins available.</p>
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Schedule a session</a>
        <p class="muted">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • Serving {{CITY}}, {{STATE}}</p>
    </div>
    <nav class="footer-nav">
      <a href="/contact.html">Contact</a>
      <a href="/conditions.html">Conditions</a>
      <a href="/book.html">Book</a>
      <a href="/privacy.html">Privacy</a>
    </nav>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
