{"path":"assets/css/styles.css","content":"/* Basic reset */
:root{
  --bg:#fffefc; --muted:#6b675f; --accent:#556b4a; --soft:#f3efe8; --card:#fff; --shadow:rgba(17,17,17,0.06);
  --maxw:1100px; --radius:12px;
  font-family: Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:#222;font-size:16px;line-height:1.45}
.container{max-width:var(--maxw);margin:0 auto;padding:48px 20px}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;border-bottom:1px solid #efece6;background:linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.6))}
.brand{display:flex;gap:12px;align-items:center}
.logo-mark{width:48px;height:48px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#7a856c);box-shadow:0 3px 8px var(--shadow)}
.brand h1{font-size:1.05rem;margin:0}
.tag{margin:0;color:var(--muted);font-size:0.9rem}
.main-nav a{margin-left:14px;color:var(--muted);text-decoration:none}
.main-nav a.cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.hero{display:grid;grid-template-columns:1fr 280px;gap:20px;align-items:stretch;padding:48px;border-bottom:1px solid #efece6}
.hero-inner h2{font-size:1.6rem;margin:0 0 8px}
.hero-inner p{color:var(--muted)}
.hero-actions{margin-top:18px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;border:0;background:#fff;color:var(--accent);cursor:pointer;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid #ddd}
.hero-pattern{width:100%;height:100%;opacity:0.9}
.story, .framework, .offers, .pricing, .testimonials, .cta{padding:36px 20px}
.features{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;list-style:none;padding:0;margin:18px 0}
.features li{background:var(--soft);padding:12px;border-radius:10px}
.flow{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));list-style:none;padding:0}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
.card{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 20px var(--shadow)}
.price{font-weight:700;color:var(--accent)}
.planner{margin-top:20px;background:linear-gradient(180deg,#fff,#fbf9f6);padding:14px;border-radius:12px;border:1px solid #efece6}
.planner form{display:grid;gap:8px}
.planner label{display:block;font-size:0.95rem}
.planner input,.planner select,.planner textarea{width:100%;padding:8px;border-radius:8px;border:1px solid #e9e6e0}
.planner textarea{min-height:80px}
.planner-actions{display:flex;gap:8px;margin-top:8px}
.plan-output{margin-top:14px;background:#fff;padding:12px;border-radius:8px;border:1px solid #eee}
.plan-output pre{white-space:pre-wrap;background:transparent;border:0;margin:0;padding:0}
.output-actions{display:flex;gap:8px;margin-top:8px}
.pricing-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.tier{background:var(--card);padding:14px;border-radius:12px}
.tier.featured{border:2px solid var(--accent)}
.testimonials blockquote{background:var(--soft);padding:12px;border-radius:10px;margin:12px 0}
.site-footer{padding:20px;border-top:1px solid #efece6;display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted);font-size:0.95rem}
/* Reveal animation */
.reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms cubic-bezier(.2,.9,.3,1),transform 520ms cubic-bezier(.2,.9,.3,1)}
.reveal.in-view{opacity:1;transform:none}
/* Respect prefers-reduced-motion */
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* Responsive */
@media (max-width:820px){
  .hero{grid-template-columns:1fr}
  .main-nav{display:none}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Set year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Scroll-triggered reveals
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var reveals = Array.prototype.slice.call(document.querySelectorAll('.reveal'));

  function revealIfVisible(el){
    var rect = el.getBoundingClientRect();
    if(rect.top < (window.innerHeight || document.documentElement.clientHeight) - 60){
      el.classList.add('in-view');
    }
  }

  if(!prefersReduced && 'IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ e.target.classList.add('in-view'); io.unobserve(e.target); }
      });
    },{threshold:0.12});
    reveals.forEach(function(r){ io.observe(r); });
  } else {
    // graceful fallback or reduced motion: show all
    reveals.forEach(function(r){ r.classList.add('in-view'); });
  }

  // Session Planner widget
  var buildBtn = document.getElementById('buildPlan');
  var copyBtn = document.getElementById('copyPlan');
  var downloadLink = document.getElementById('downloadPlan');
  var clearBtn = document.getElementById('clearPlan');
  var planText = document.getElementById('planText');

  function gatherInputs(){
    var goal = document.getElementById('goal').value;
    var modalities = Array.from(document.getElementById('modalities').selectedOptions).map(function(o){return o.value;});
    var minutes = document.getElementById('dailyMinutes').value || '0';
    var freq = document.getElementById('frequency').value;
    var notes = document.getElementById('notes').value.trim();
    return {goal:goal,modalities:modalities,minutes:minutes,freq:freq,notes:notes};
  }

  function synthesizePlan(data){
    var lines = [];
    lines.push('Personal 4-week plan — ' + (new Date()).toLocaleDateString());
    lines.push('Goal: ' + data.goal);
    lines.push('Preferred supports: ' + (data.modalities.length?data.modalities.join(', '):'None selected'));
    lines.push('Daily commitment: ' + data.minutes + ' minutes');
    lines.push('Session rhythm: ' + (data.freq === '0.5' ? 'Fortnightly' : data.freq + 'x per week'));
    lines.push('');
    lines.push('Week 1 — gentle introduction:');
    lines.push('- Choose one short practice from the list below to try 3–5x this week.');
    if(data.modalities.indexOf('Breathwork')>-1) lines.push('  • 3-minute paced breathing after waking');
    if(data.modalities.indexOf('Movement')>-1) lines.push('  • 8-minute morning mobility sequence');
    if(data.modalities.indexOf('Nutrition support')>-1) lines.push('  • Simple food log for 3 meals/day');
    if(data.modalities.indexOf('Herbal or nutrient suggestions')>-1) lines.push('  • Brief trial of recommended nutrient (as discussed in session)');
    lines.push('');
    lines.push('Week 2 — build consistency:');
    lines.push('- Repeat selected practice; add one micro-habit around sleep or stress management.');
    lines.push('');
    lines.push('Weeks 3–4 — adjust and track:');
    lines.push('- Note what changed; increase practice frequency by 1–2 reps or minutes if comfortable.');
    if(data.notes) { lines.push(''); lines.push('Notes / constraints: ' + data.notes); }
    lines.push('');
    lines.push('Simple tracking: mark days when the practice occurred and write one sentence about effect.');
    lines.push('If symptoms persist or shift, consider scheduling a brief follow-up to review data and refine steps.');
    return lines.join('\n');
  }

  function updateDownload(text){
    var blob = new Blob([text],{type:'text/plain'});
    var url = URL.createObjectURL(blob);
    downloadLink.href = url;
  }

  if(buildBtn){
    buildBtn.addEventListener('click', function(){
      var data = gatherInputs();
      var plan = synthesizePlan(data);
      planText.textContent = plan;
      updateDownload(plan);
    });
  }

  if(copyBtn){
    copyBtn.addEventListener('click', function(){
      var text = planText.textContent || '';
      if(!navigator.clipboard){
        // fallback
        var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); }catch(e){} document.body.removeChild(ta);
        alert('Plan copied to clipboard');
        return;
      }
      navigator.clipboard.writeText(text).then(function(){
        copyBtn.textContent = 'Copied';
        setTimeout(function(){ copyBtn.textContent = 'Copy summary'; },1500);
      }).catch(function(){ alert('Could not copy — please try manually.'); });
    });
  }

  if(clearBtn){
    clearBtn.addEventListener('click', function(){
      document.getElementById('plannerForm').reset();
      planText.textContent = 'No plan yet. Use the builder to generate a simple outline you can try.';
      downloadLink.href = '#';
    });
  }

})();"} 
